    // 判断是否需要解码（检测是否是base64编码的特征）
    if(result && /^[A-Za-z0-9+/]+={0,2}$/.test(result) && result.length % 4 === 0){
        try {
            var decoded = java.base64Decode(result);
            return decoded;
        } catch(e) {
            return result;
        }
    }
    // 非base64数据直接返回
    return result;
})()

